items = []
def add(id, name, desc, dur, concepts, outcomes, methods, metrics, pitfalls, tools, lab, data, assess, books, papers, trends, hw, cap, deliver):
    d = {"module_name": name, "module_description": desc, "duration_weeks": dur,
         "core_concepts": concepts, "learning_outcomes": outcomes, "methods_models": methods,
         "evaluation_metrics": metrics, "pitfalls_limitations": pitfalls, "tools_stack": tools,
         "commercial_platforms": hw.get("cp", "[uncertain] - commercial platforms demoed selectively per module"),
         "tools_access_cost": hw.get("cost", "[uncertain] - pricing changes fast; verify vendor quote each offering"),
         "lab_activities": lab, "datasets_apis": data, "data_collection_workflow": hw.get("dc",
             "Collect via API or scrape, store raw JSON/CSV with timestamp, deduplicate and add derived columns, document schema and rate limits, then analyse."),
         "assessment_methods": assess, "textbooks": books, "key_papers": papers,
         "trends_2024_2026": trends, "industry_relevance": hw["ind"], "localization_context": hw["loc"],
         "ethics_regulation": hw["eth"], "case_study_scenarios": cap, "deliverable_format": deliver,
         "uncertain": hw.get("unc", [])}
    items.append((id, d))

